!function(e){function r(r){for(var i,a,o=r[0],p=r[1],d=r[2],s=0,y=[];s<o.length;s++)a=o[s],Object.prototype.hasOwnProperty.call(n,a)&&n[a]&&y.push(n[a][0]),n[a]=0;for(i in p)Object.prototype.hasOwnProperty.call(p,i)&&(e[i]=p[i]);for(g&&g(r);y.length;)y.shift()();return m.push.apply(m,d||[]),t()}function t(){for(var e,r=0;r<m.length;r++){for(var t,a=m[r],o=!0,p=1;p<a.length;p++)t=a[p],0!==n[t]&&(o=!1);o&&(m.splice(r--,1),e=i(i.s=a[0]))}return e}function i(r){if(a[r])return a[r].exports;var t=a[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,i),t.l=!0,t.exports}var a={},n={46:0},m=[];i.m=e,i.c=a,i.d=function(e,r,t){i.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},i.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},i.t=function(e,r){if(1&r&&(e=i(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(i.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var a in e)i.d(t,a,function(r){return e[r]}.bind(null,a));return t},i.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return i.d(r,"a",r),r},i.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},i.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=r,o=o.slice();for(var d=0;d<o.length;d++)r(o[d]);var g=p;m.push([46,0]),t()}({46:function(e,r,t){"use strict";t.r(r);var i=t(0);Object(i.a)("de","army",t(47),t(1))},47:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"“猎虎”重型坦克歼击车","description":"<p>“猎虎”重型坦克歼击车是以虎王坦克底盘及其部件改装而成的一种重型自行反坦克炮车，它安装了1门128mm50倍口径的Pak44 L/55型反坦克火炮（但后来由于生产128mm火炮的工厂遭到盟军空袭被破坏，造成128mm火炮的缺乏，故有小部分“猎虎”只能选用88mm坦克炮），128mm火炮是二战中威力最强大的反坦克炮，它可以在1000m距离上击穿230mm厚的装甲，它更可以在苏军坦克和盟军坦克的火炮射程外击毁对方。该车战斗室的正面装甲厚度达到250mm，超过了虎王坦克炮塔的厚度，防护能力相当强。该车重达70吨，是德军在二战中最重的装甲车辆。</p><p>“猎虎”重型坦克歼击车在1944年7月开始生产，直到1945年欧洲战事结束，一共才生产了77辆，由于生产数量太少，这些炮车只装备了德军653和512这二个重装甲歼击营，其中653重装甲歼击营参加了西线的阿登反击战，512重装甲歼击营则参加了东线匈牙利的布达佩斯保卫战，后来它们又一起参加了德国本土最后的防御战，在这几场激烈的战斗中，“猎虎”重型坦克歼击车尽管在一些局部战斗中占有优势，也取得一些战绩，但此时德军大势已去，在苏军与盟军的大军碾压下，这些“猎虎”不是被对手击毁，或是在败退时被车组人员自毁，基本无一幸存。</p>","part1title":"","part1description":"","part1content":[{"image":"{{image}}imgs/de/army/de_army_tankdestroyertiger_11.jpg{{text}}“猎虎”重型坦克歼击车四视图{{image}}imgs/de/army/de_army_tankdestroyertiger_12.jpg","description":"<h6>“猎虎”重型坦克歼击车<br>型号：Jagdtiger （Sdkfz 186）</h6><p>参数：车长：10.65m，车宽：3.63m，车高：2.95m，车重：70.0t；乘员：6人。</p><p>最高车速：38km/h，最大行程：170km；</p><p>装甲厚度：车体前部：100-250mm，车体两侧：80mm，车体后部：80mm，车体顶部：40mm，车体底部：25-40mm。</p><p>武器配备：1门128mm 50倍口径的Pak44 L/55型反坦克火炮（炮塔可在左右各10度范围内转动）； 1挺MG34型7.92mm机枪；</p><p>弹药配备：炮弹38发，机枪弹2925发。</p>","caption":""}],"part2title":"战场上的“猎虎”重型坦克歼击车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyertiger_21.jpg","description":"1945年3月22日，在德国“葡萄酒之路”上的诺伊施塔特作战的653重装甲歼击营第3连编号323“猎虎”重型坦克歼击车。这个战斗群伏击了行驶在诺伊施塔特路上的一支美军坦克纵队，使美军遭受到严重损失（德军声称此次战斗击毁了25辆美军谢尔曼坦克）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_22.jpg","description":"1945年4月在德国本土作战的一辆“猎虎”重型坦克歼击车（可能是隶属512重装甲歼击营），车上用树技作了伪装。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_23.jpg","description":"1945年，德国战场上隶属653重装甲歼击营的一辆“猎虎”重型坦克歼击车，该车涂的是冬季伪装色。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_24.jpg","description":"1944年9月初，653重装甲歼击营第1连和第3连在德国训练营地接收了三辆“猎虎”重型坦克歼击车，正准备用火车运往前线驻地。这些“猎虎”已敷设了防磁层和“+”标志，但尚未涂上伪装迷彩色。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_25.jpg","description":"1944年西线战场，一辆到达前线营地的德军653重装甲歼击营的“猎虎”重型坦克歼击车，车组人员正在将运输专用履带更换为战斗用的履带。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_26.jpg","description":"1944年冬天，653重装甲歼击营第3连一辆在树林中待命的“猎虎”重型坦克歼击车，该车用树枝等作了伪装，一名德军士兵在车旁警卫。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_27.jpg","description":"653重装甲歼击营编号314的“猎虎”重型坦克歼击车正在补充弹药，该车引擎上放着几发128mm火炮的炮弹。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_28.jpg","description":"1945年初春，653重装甲歼击营314号“猎虎”重型坦克歼击车遭到盟军飞机空袭，但未有受损，该车虽然作了伪装，且隐藏在树林中，但由于车体太大，且留下的履带痕迹十分明显，因此很容易飞机发现。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_29.jpg","description":"653重装甲歼击营一辆“猎虎”重型坦克歼击车正被火车运往前线驻地，当时由于盟军飞机空袭频繁，被运输的“猎虎”也要做全车伪装，并且火车也只能在晚间开行。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_30.jpg","description":"1945年3月德国本土战场，653重装甲歼击营第2 连一辆“猎虎”重型坦克歼击车渡过莱茵河后在一墓地待命，这部“猎虎”全车（包括炮管）已罩上一层伪装网。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_31.jpg","description":"1945年3月德国战场，一辆“猎虎”重型坦克歼击车正经林茨市向东行进。这辆“猎虎”因受空袭受损，刚修复好就编入德国党卫军第1装甲师一个战斗群赶赴前线参加战斗。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_32.jpg","description":"1945年3月23日，埋伏在德国诺伊施塔特附近的653重装甲歼击营331号和323号二辆“猎虎”重型坦克歼击车在美军的攻击下被迫退入城区，撒退中这二辆车多次被美军坦克击中，但美军坦克炮弹却无法击穿它们厚重的装甲；退入城区后，323号车因减速器损坏而抛锚在一花园中，331号车则停靠在一房子前继续向美军开火，后也因减速器故障而无法行驶，该车组人员在射完最后一发炮弹后作出一些破坏措施后撒离。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_33.jpg","description":"美军进入德国诺伊施塔特城区，一支美军车队正从遗弃的331号“猎虎”重型坦克歼击车旁边道路经过，一些美军人员在检查331号“猎虎”的损毁情况。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_34.jpg","description":"这是在德国诺伊施塔特城区，1945年3月23日被德军遗弃的331号“猎虎”重型坦克歼击车，这是一张难得的彩照。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_35.jpg","description":"1945年3月德国本土战场，653重装甲歼击营遗弃在一铁路道口的编号234号“猎虎”重型坦克歼击车，该车已遭盟军摧毁，一群美军士兵正在查看这部“猎虎”残骸。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_36.jpg","description":"1945年3月30日，德国施伟青根市（音译）内一辆“猎虎”重型坦克歼击车的残骸，它是在200米左右距离被美军谢尔曼坦克击中起火而损毁。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyertiger_37.jpg","description":"德军653重装甲歼击营一辆在向阿尔卑斯山撒退途中损毁的“猎虎”重型坦克歼击车，它的残骸遗弃在德国慕尼黑附近。","caption":""}]}')}});